_ALPHA_TO_NUM = {ch: i + 1 for i, ch in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZ")}


def _normalize_tier(raw, tier_type):
    """Returns int tier number or None."""
    if raw is None or raw == "":
        return None
    if tier_type == "alpha":
        return _ALPHA_TO_NUM.get(str(raw).upper())
    if tier_type == "numeric":
        try:
            return int(raw)
        except (ValueError, TypeError):
            return None
    return None


def _parse(pos):
    """
    Returns tuple: (block, bay, row, tier_int, parse_fail_int)

    1. Not a yard position (no yard prefix)       -> all NULL, parse_fail = 0
    2. Standard yard slot                         -> block/bay/row/tier, parse_fail = 0
    3. Special/buffer area (e.g. Y-CT03-EXAM)     -> block = area code, row = "Buffer", parse_fail = 0
    4. Prefix matches but nothing above matches   -> all NULL, parse_fail = 1
    """
    cfg = TERMINAL_PARSERS[TERMINAL_CODE] if TERMINAL_CODE in TERMINAL_PARSERS \
          else TERMINAL_PARSERS[DEFAULT_PARSER]

    if not pos or not str(pos).startswith(cfg["yard_prefix"]):
        return (None, None, None, None, 0)

    pos = str(pos).strip()
    m = cfg["yard_pattern"].match(pos)
    if m:
        g = cfg["groups"]
        tier_int = _normalize_tier(m.group(g["tier"]), cfg["tier_type"])
        return (m.group(g["block"]), m.group(g["bay"]), m.group(g["row"]),
                int(tier_int) if tier_int is not None else None, 0)

    code = pos.replace(cfg["yard_prefix"], "", 1)
    if cfg["special_pattern"].match(code):
        return (code, None, "Buffer", None, 0)

    return (None, None, None, None, 1)


_PARSE_SCHEMA = StructType([
    StructField("block",      StringType()),
    StructField("bay",        StringType()),
    StructField("row",        StringType()),
    StructField("tier",       ShortType()),
    StructField("parse_fail", IntegerType()),
])


@F.udf(returnType=_PARSE_SCHEMA)
def parse_position_udf(pos):
    return _parse(pos)

from notebookutils import mssparkutils

def list_csv(path):
    try:
        items = mssparkutils.fs.ls(path)
    except Exception:
        return []
    out = []
    for it in items:
        if it.isDir:
            out += list_csv(it.path)
        elif it.name.lower().endswith(".csv"):
            out.append(it)
    return out

